INSERT INTO academy_courses (slug, title, description, icon, color, order_index, difficulty, requires_pro, is_published) VALUES
  ('portfolio-diversification', 'Building a Portfolio: Diversification & Risk', 'One stock is a bet. A portfolio is a strategy. Learn diversification, position sizing, and risk before you build yours.', 'PieChart', 'emerald', 5, 'beginner', FALSE, TRUE)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO academy_lessons (course_id, slug, title, type, order_index, xp_reward, content)
SELECT
  (SELECT id FROM academy_courses WHERE slug = 'portfolio-diversification'),
  v.slug, v.title, v.type, v.order_index, v.xp_reward, v.content
FROM (VALUES
  ('why-diversification-matters', 'Why Diversification Matters', 'read', 0, 10, '{"sections":[{"text":"Diversification is a fancy word for a simple idea: don''t put all your eggs in one basket. Instead of buying just one company''s stock, you spread your money across many different investments. That way, if one of them stumbles, the others can help cushion the fall.","highlightedTerms":[{"term":"Diversification","definition":"Spreading your money across many different investments so no single one can sink your whole portfolio."}]},{"text":"The opposite of diversification is concentration risk — having too much money riding on one stock or one industry. Imagine putting your entire life savings into a single company. If that company has a bad year, so do you. Spreading things out means no single bad event can wipe you out.","highlightedTerms":[{"term":"Concentration Risk","definition":"The danger of having too much money riding on one stock or industry — if it stumbles, so does a big chunk of your portfolio."}]},{"text":"Here''s the tricky part: owning 10 stocks isn''t truly diversified if they''re all in the same industry. If you own 10 tech companies, they often rise and fall together — this is called high correlation. When the whole tech sector has a bad day, all 10 of your stocks can drop at once, so you haven''t really spread your risk. True diversification means owning things that don''t all move in the same direction, like a mix of tech, healthcare, energy, and consumer goods.","highlightedTerms":[{"term":"Correlation","definition":"How closely two investments move together. Stocks in the same industry often have high correlation, so owning many of them isn''t as diversified as it looks."}]}],"funFact":"During the 2000 dot-com crash, investors who owned ''lots'' of stocks were shocked to lose big — because nearly all their stocks were internet and tech companies that all fell together. It was a painful lesson that variety, not just volume, is what protects you."}'::jsonb),
  ('position-sizing-and-risk', 'Position Sizing & Risk', 'read', 1, 10, '{"sections":[{"text":"Imagine you have $1,000 to invest and you put all of it into one company''s stock. If that company stumbles, your entire savings takes the hit. Position sizing is simply the practice of deciding how much money to put into any single investment — so that one bad pick can''t sink your whole plan.","highlightedTerms":[{"term":"Position Sizing","definition":"Deciding how much of your total money to put into a single investment, so no one bet can hurt you too badly."}]},{"text":"A common beginner guideline is to keep any single position to a small slice of your total portfolio — often no more than 5% to 10%. That way, if one stock drops sharply, you still have most of your money working in other places. Spreading money across many investments is called diversification, and it''s one of the simplest ways to lower risk.","highlightedTerms":[{"term":"Portfolio","definition":"The full collection of all the investments you own, viewed together as one group."},{"term":"Diversification","definition":"Spreading your money across many different investments so a single loss doesn''t hurt too much."}]},{"text":"Risk tolerance is how much ups-and-downs you can handle — both financially and emotionally — without panicking or losing sleep. A beginner often has a lower risk tolerance because they have less experience riding out scary drops and may need their money sooner. An experienced investor might accept bigger swings because they''ve seen markets recover before and have a longer timeline to wait.","highlightedTerms":[{"term":"Risk Tolerance","definition":"How much loss and price swinging you can comfortably handle without panicking or needing to sell."}]},{"text":"There''s no single ''correct'' size — it depends on your goals, your timeline, and how well you sleep at night when prices fall. Starting small while you learn is a smart, low-pressure way to build confidence. As you gain experience, you can adjust your position sizes to match your growing comfort.","highlightedTerms":[{"term":"Timeline","definition":"How long you plan to keep your money invested before you''ll need to use it."}]}],"funFact":"Professional traders often follow a ''1% rule'' — never risking more than 1% of their total account on any single trade, no matter how confident they feel."}'::jsonb),
  ('portfolio-basics-quiz', 'Quick Check: Portfolio Basics', 'quiz', 2, 20, '{"questions":[{"question":"Why do investors spread their money across many different investments instead of putting it all in one?","options":["To make sure every investment goes up at the same time","So that if one investment does poorly, the others can help cushion the loss","Because owning more things always guarantees higher returns","To avoid ever paying any taxes"],"correctIndex":1,"explanation":"Diversification means not putting all your eggs in one basket — spreading out lowers the risk that one bad investment ruins your whole portfolio."},{"question":"Two investments are described as having ''low correlation.'' What does that mean?","options":["They tend to move up and down together at the same time","They tend to move independently, often in different directions","They are guaranteed to both lose money","They are the exact same investment"],"correctIndex":1,"explanation":"Correlation measures how closely two investments move together. Low correlation means they don''t move in lockstep, which helps smooth out your overall ups and downs."},{"question":"What is ''position sizing'' mostly about?","options":["Choosing how much money to put into any single investment","Picking the tallest company to invest in","Deciding what time of day to buy stocks","Measuring how big a company''s headquarters is"],"correctIndex":0,"explanation":"Position sizing is deciding how much of your money goes into one investment, so a single loser can''t sink your whole portfolio."}]}'::jsonb),
  ('portfolio-terms-match', 'Match the Portfolio Terms', 'match', 3, 15, '{"pairs":[{"term":"Diversification","definition":"Spreading your money across many investments so one bad pick can''t sink you."},{"term":"Correlation","definition":"How closely two investments move up and down together."},{"term":"Position Size","definition":"How much money you put into one single investment."},{"term":"Asset Allocation","definition":"How you split your money between types like stocks, bonds, and cash."}]}'::jsonb),
  ('building-your-first-portfolio', 'Building Your First Portfolio', 'scenario', 4, 25, '{"setup":"You just built your first portfolio! Here''s what you own: 80% split across three tech companies (a phone maker, a software giant, and a chip company), and 20% in a single stock your friend swore would ''go to the moon.'' Feeling proud, you show it to someone who knows investing. Is this a well-diversified portfolio, and what should you do?","choices":[{"label":"It''s great! I own four different companies, so my money is spread out safely.","feedback":"It''s true you own four companies, but they''re not really spread out. Three of your four holdings are tech stocks, and tech companies often rise and fall together. If the tech industry has a bad year, most of your portfolio drops at once. Owning several stocks isn''t the same as being diversified — what matters is owning things that DON''T all move together.","isCorrect":false},{"label":"I should add a couple more hot tech stocks to boost my returns even higher.","feedback":"This is a tempting trap! Chasing more winners feels exciting, but adding more tech would make your portfolio even more lopsided. You''d be putting even more eggs in one basket. Diversification isn''t about finding more good bets — it''s about making sure one bad event can''t sink everything you own.","isCorrect":false},{"label":"My money is too concentrated in tech and one risky tip. I should spread it across different industries and consider a broad fund.","feedback":"Exactly right! You spotted the real problem: ''concentration risk'' — too much riding on one area. Because tech stocks tend to move together, and your friend''s tip is a gamble, one rough patch could hit almost everything at once. Spreading money across different industries (like healthcare, energy, or everyday goods), or using a broad index fund that holds hundreds of companies, cushions the blow when any single area struggles. Good investors protect against being wrong, not just bet on being right.","isCorrect":true}]}'::jsonb)
) AS v(slug, title, type, order_index, xp_reward, content)
ON CONFLICT (course_id, slug) DO NOTHING;
